SELECT (SELECT COUNT(*) FROM customers WHERE Segment='LAM') AS lam_all,
       (SELECT COUNT(*) FROM yearmonth y JOIN customers c ON y.CustomerID=c.CustomerID WHERE c.Segment='LAM') AS lam_records,
       (SELECT COUNT(DISTINCT y.CustomerID) FROM yearmonth y JOIN customers c ON y.CustomerID=c.CustomerID WHERE c.Segment='LAM') AS lam_with_records;
